    {
      "name": "Int.Matrix.exists_ne_zero_int_vec_norm_le'",
      "module_name": "Mathlib.NumberTheory.SiegelsLemma",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : Fintype α] [inst_1 : Fintype β] (A : Matrix α β ℤ),\n  Fintype.card α < Fintype.card β →\n    0 < Fintype.card α →\n      A ≠ 0 →\n        ∃ t,\n          t ≠ 0 ∧\n            A.mulVec t = 0 ∧\n              ‖t‖ ≤ (↑(Fintype.card β) * ‖A‖) ^ (↑(Fintype.card α) / (↑(Fintype.card β) - ↑(Fintype.card α)))"
    },
    {
      "name": "NumberField.house.exists_ne_zero_int_vec_house_le",
      "module_name": "Mathlib.NumberTheory.NumberField.House",
      "kind": "theorem",
      "type": "∀ (K : Type u_1) [inst : Field K] [inst_1 : NumberField K] {α : Type u_2} {β : Type u_3}\n  (a : Matrix α β (NumberField.RingOfIntegers K)),\n  a ≠ 0 →\n    ∀ {p q : ℕ},\n      0 < p →\n        p < q →\n          ∀ [inst_2 : Fintype β],\n            Fintype.card β = q →\n              ∀ {A : ℝ},\n                (∀ (k : α) (l : β), NumberField.house ((algebraMap (NumberField.RingOfIntegers K) K) (a k l)) ≤ A) →\n                  ∀ [inst_3 : DecidableEq (K →+* ℂ)] [inst_4 : Fintype α],\n                ..."
    },
    {
      "name": "MvPolynomial.combinatorial_nullstellensatz_exists_eval_nonzero",
      "module_name": "Mathlib.Combinatorics.Nullstellensatz",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {σ : Type u_2} [Finite σ] [IsDomain R] (f : MvPolynomial σ R) (t : σ →₀ ℕ),\n  MvPolynomial.coeff t f ≠ 0 →\n    f.totalDegree = Finsupp.degree t →\n      ∀ (S : σ → Finset R), (∀ (i : σ), t i < (S i).card) → ∃ s, (∀ (i : σ), s i ∈ S i) ∧ (MvPolynomial.eval s) f ≠ 0"
    },
    {
      "name": "HasFPowerSeriesAt.iterate_dslope_fslope_ne_zero",
      "module_name": "Mathlib.Analysis.Analytic.IsolatedZeros",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_1} [inst : NontriviallyNormedField 𝕜] {E : Type u_2} [inst_1 : NormedAddCommGroup E]\n  [inst_2 : NormedSpace 𝕜 E] {p : FormalMultilinearSeries 𝕜 𝕜 E} {f : 𝕜 → E} {z₀ : 𝕜},\n  HasFPowerSeriesAt f p z₀ → p ≠ 0 → (Function.swap dslope z₀)^[p.order] f z₀ ≠ 0"
    },
    {
      "name": "MvPolynomial.instFiniteSubtypeMemSubmoduleRestrictTotalDegreeOfFinite",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Basic",
      "kind": "instance",
      "type": "∀ (σ : Type u) (R : Type v) [inst : CommSemiring R] [Finite σ] (N : ℕ),\n  Module.Finite R ↥(MvPolynomial.restrictTotalDegree σ R N)"
    },
    {
      "name": "Poly.isPoly",
      "module_name": "Mathlib.NumberTheory.Dioph",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} (f : Poly α), IsPoly ⇑f"
    },
    {
      "name": "MvPolynomial.instFiniteSubtypeMemSubmoduleRestrictDegreeOfFinite",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Basic",
      "kind": "instance",
      "type": "∀ (σ : Type u) (R : Type v) [inst : CommSemiring R] [Finite σ] (N : ℕ),\n  Module.Finite R ↥(MvPolynomial.restrictDegree σ R N)"
    },
    {
      "name": "Polynomial.card_eq_of_natDegree_le_of_coeff_le",
      "module_name": "Mathlib.NumberTheory.MahlerMeasure",
      "kind": "theorem",
      "type": "∀ {n : ℕ} {B₁ B₂ : Fin (n + 1) → ℝ},\n  {p | p.natDegree ≤ n ∧ ∀ (i : Fin (n + 1)), B₁ i ≤ ↑(p.coeff ↑i) ∧ ↑(p.coeff ↑i) ≤ B₂ i}.ncard =\n    ∏ i, (⌊B₂ i⌋ - ⌈B₁ i⌉ + 1).toNat"
    }
  ]
}
